    "Add unit tests for product-name safety and canonical serialization, divergent or non-SemVer coordinated versions, one exact product tag, forbidden per-package tag or forge operations, duplicate identities, and strict unknown-field/schema rejection.",
    "Run rtk just test; expected: all model tests pass, including the new product-operation successor tests.",
    "Run rtk just fmt-check and rtk just lint; expected: both exit zero."
  ],
  "commit_message": "feat(model): add coordinated product release operations",
  "covers_criteria": [
    "AC-001",
    "AC-002",
    "AC-010",
    "AC-011"
  ]
}
{
  "id": "PM-002",
  "title": "Stage nonbreaking artifact inventory, canonical digest chain and metadata",
  "files": {
    "modify": [
      "crates/callisto-model/src/release.rs"
    ],
    "test": [
      "crates/callisto-model/src/release.rs"
    ]
  },
