    impl ProvenancePolicy {
        fn new(
            repository: GitHubRepository,
            workflow_path: impl Into<String>,
            workflow_commit: CommitSha,
        ) -> Result<Self, SuccessorError> {
            let workflow_path = workflow_path.into();
            if !is_safe_workflow_path(&workflow_path) {
                return Err(SuccessorError::InvalidProvenance);
            }
            Ok(Self {
                repository,
                workflow_path,
                workflow_commit,
                github_attestation_required: true,
            })
        }

        fn validate(&self) -> Result<(), SuccessorError> {
            if !self.github_attestation_required || !is_safe_workflow_path(&self.workflow_path) {
                return Err(SuccessorError::InvalidProvenance);
            }
            Ok(())
        }
    }

