        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            Some(self.cmp(other))
        }
    }

    impl Ord for ReleaseArtifactSlot {
        fn cmp(&self, other: &Self) -> Ordering {
            serde_json::to_vec(self)
                .expect("closed artifact slot serializes")
                .cmp(&serde_json::to_vec(other).expect("closed artifact slot serializes"))
        }
    }

