        fn release() -> ProductReleaseId {
            ProductReleaseId::from_coordinated_versions(
                ProductName::parse("callisto").unwrap(),
                [Version::semver(1, 2, 3), Version::semver(1, 2, 3)],
            )
            .unwrap()
