        #[test]
        fn complete_observation_receipt_is_exact_safe_and_canonical() {
            let intent = intent();
            let operations = intent
                .operations
                .iter()
                .enumerate()
                .map(|(index, operation)| ObservedOperation {
                    operation: operation.id.clone(),
                    evidence: match &operation.id {
                        ReleaseOperationId::ProductTag { release, tag } => ReleaseObservationEvidence::RemoteTag {
                            release: release.clone(),
                            name: tag.clone(),
                            target: intent.source_commit.clone(),
                            annotation_digest: ArtifactDigest::from_bytes("tag"),
                        },
                        ReleaseOperationId::ForgePrepare { release, .. } => ReleaseObservationEvidence::ForgeRelease {
                            release: release.clone(),
                            lifecycle: ForgeLifecycle::Draft,
                            asset_roster_digest: ArtifactDigest::from_bytes("draft"),
                        },
                        ReleaseOperationId::ForgePublish { release, .. } => ReleaseObservationEvidence::ForgeRelease {
                            release: release.clone(),
                            lifecycle: ForgeLifecycle::Published,
                            asset_roster_digest: ArtifactDigest::from_bytes("published"),
                        },
                        ReleaseOperationId::ArtifactUpload { release, slot } => {
                            ReleaseObservationEvidence::ForgeAsset {
                                release: release.clone(),
                                slot: slot.clone(),
                                digest: ArtifactDigest::from_bytes(slot.file_name()),
                                byte_length: 1,
                            }
                        }
                        ReleaseOperationId::RegistryArtifactPublish {
                            package,
                            version,
                            registry,
                            slot,
                        } => ReleaseObservationEvidence::RegistryArtifact {
                            package: package.clone(),
                            version: version.clone(),
                            registry: registry.clone(),
                            slot: slot.clone(),
                            digest: ArtifactDigest::from_bytes(slot.file_name()),
                            byte_length: 1,
                        },
                    },
                    provenance: if index == 0 {
                        ObservationProvenance::NewlyProduced
                    } else {
                        ObservationProvenance::AlreadyPresent
                    },
                })
                .collect::<Vec<_>>();
            let receipt = CompleteObservationReceipt::new(&intent, operations).unwrap();
            assert!(receipt.validate_for_intent(&intent).is_ok());
            assert_eq!(
                serde_json::from_value::<CompleteObservationReceipt>(serde_json::to_value(&receipt).unwrap()).unwrap(),
                receipt
            );
            let mut unknown = serde_json::to_value(&receipt).unwrap();
            unknown["unexpected"] = serde_json::Value::Bool(true);
            assert!(serde_json::from_value::<CompleteObservationReceipt>(unknown).is_err());
            let mut missing = receipt.operations.clone();
            missing.pop();
            assert!(matches!(
                CompleteObservationReceipt::new(&intent, missing),
                Err(SuccessorError::MismatchedObservationRoster)
            ));
            let mut reordered = receipt.operations.clone();
            reordered.swap(0, 1);
            assert!(matches!(
                CompleteObservationReceipt::new(&intent, reordered),
                Err(SuccessorError::MismatchedObservationRoster)
            ));
            let mut wrong = receipt.operations.clone();
            wrong[0].evidence = ReleaseObservationEvidence::ForgeRelease {
                release: intent.product_release.clone(),
                lifecycle: ForgeLifecycle::Draft,
                asset_roster_digest: ArtifactDigest::from_bytes("wrong"),
            };
            assert!(matches!(
                CompleteObservationReceipt::new(&intent, wrong),
                Err(SuccessorError::MismatchedObservationEvidence)
            ));
        }
    }
