    impl CompleteObservationReceipt {
        const SCHEMA_VERSION: u8 = 1;

        fn new(intent: &ReleaseIntent, operations: Vec<ObservedOperation>) -> Result<Self, SuccessorError> {
            if operations
                .iter()
                .map(|entry| &entry.operation)
                .ne(intent.operations.iter().map(|operation| &operation.id))
            {
                return Err(SuccessorError::MismatchedObservationRoster);
            }
            for entry in &operations {
                validate_evidence(intent, entry)?;
            }
            Ok(Self {
                schema_version: Self::SCHEMA_VERSION,
                intent_digest: intent.digest.clone(),
                operations,
            })
        }

        fn validate_for_intent(&self, intent: &ReleaseIntent) -> Result<(), SuccessorError> {
            if self.schema_version != Self::SCHEMA_VERSION || self.intent_digest != intent.digest {
                return Err(SuccessorError::MismatchedObservationIntent);
            }
            Self::new(intent, self.operations.clone()).map(|_| ())
        }
    }

    impl<'de> Deserialize<'de> for CompleteObservationReceipt {
        fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
        where
            D: Deserializer<'de>,
        {
            let wire = CompleteObservationReceiptWire::deserialize(deserializer)?;
            if wire.schema_version != Self::SCHEMA_VERSION {
                return Err(serde::de::Error::custom("unsupported observation receipt schema"));
            }
            Ok(Self {
                schema_version: wire.schema_version,
                intent_digest: wire.intent_digest,
                operations: wire.operations,
            })
        }
    }

    fn validate_evidence(intent: &ReleaseIntent, entry: &ObservedOperation) -> Result<(), SuccessorError> {
        match (&entry.operation, &entry.evidence) {
            (
                ReleaseOperationId::RegistryArtifactPublish {
                    package,
                    version,
                    registry,
                    slot,
                },
                ReleaseObservationEvidence::RegistryArtifact {
                    package: evidence_package,
                    version: evidence_version,
                    registry: evidence_registry,
                    slot: evidence_slot,
                    ..
                },
            ) if package == evidence_package
                && version == evidence_version
                && registry == evidence_registry
                && slot == evidence_slot =>
            {
                Ok(())
            }
            (
                ReleaseOperationId::ProductTag { release, tag },
                ReleaseObservationEvidence::RemoteTag {
                    release: evidence_release,
                    name,
                    target,
                    ..
                },
            ) if release == evidence_release && tag == name && target == &intent.source_commit => Ok(()),
            (
                ReleaseOperationId::ForgePrepare { release, .. },
                ReleaseObservationEvidence::ForgeRelease {
                    release: evidence_release,
                    ..
                },
            ) if release == evidence_release => Ok(()),
            (
                ReleaseOperationId::ForgePublish { release, .. },
                ReleaseObservationEvidence::ForgeRelease {
                    release: evidence_release,
                    lifecycle: ForgeLifecycle::Published,
                    ..
                },
            ) if release == evidence_release => Ok(()),
            (
                ReleaseOperationId::ArtifactUpload { release, slot },
                ReleaseObservationEvidence::ForgeAsset {
                    release: evidence_release,
                    slot: evidence_slot,
                    ..
                },
            ) if release == evidence_release && slot == evidence_slot => Ok(()),
            _ => Err(SuccessorError::MismatchedObservationEvidence),
        }
    }

