    fn canonical_checksum_bytes(
        payload_entries: &[ReleaseArtifactEntry],
        metadata_entry: &ReleaseArtifactEntry,
    ) -> Result<Vec<u8>, SuccessorError> {
        let mut entries = payload_entries
            .iter()
            .filter_map(|entry| match entry.slot {
                ReleaseArtifactSlot::ProductAsset { .. } => Some(ChecksumRosterEntry {
                    file_name: entry.slot.file_name().to_string(),
                    digest: entry.digest.clone(),
                }),
                ReleaseArtifactSlot::RegistryPackage { .. }
                | ReleaseArtifactSlot::ChecksumManifest { .. }
                | ReleaseArtifactSlot::ReleaseMetadata { .. } => None,
            })
            .collect::<Vec<_>>();
        entries.push(ChecksumRosterEntry {
            file_name: metadata_entry.slot.file_name().to_string(),
            digest: metadata_entry.digest.clone(),
        });
        entries.sort_by(|left, right| left.file_name.cmp(&right.file_name));
        if entries.len() != 5
            || entries.iter().any(|entry| entry.file_name == CHECKSUM_FILE_NAME)
            || entries.windows(2).any(|pair| pair[0].file_name == pair[1].file_name)
        {
            return Err(SuccessorError::InvalidChecksumRoster);
        }
        Ok(entries
            .into_iter()
            .flat_map(|entry| entry.line().into_bytes())
            .collect())
    }

