    /// Returns the repository-name component.
    pub fn repo(&self) -> &str {
        &self.repo
    }

    /// Renders the canonical `owner/repo` slug, for example for `gh --repo`.
    pub fn as_slug(&self) -> String {
        format!("{}/{}", self.owner, self.repo)
    }
