    /// Exact, provider-neutral facts retained only after graph has verified an
    /// operation. Deliberately no endpoint, headers, stderr, or free-form
    /// provider text can be represented here.
    #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
    #[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
    enum ReleaseObservationEvidence {
        RegistryArtifact {
            schema_version: u8,
            package: ReleasePackageId,
            version: Version,
            #[serde(flatten)]
            registry: RegistryBindingId,
            slot: ReleaseArtifactSlot,
            digest: ArtifactDigest,
            byte_length: u64,
        },
        RemoteTag {
            schema_version: u8,
            release: ProductReleaseId,
            name: String,
            target: CommitSha,
            annotation_digest: ArtifactDigest,
        },
        ForgePrepare {
            schema_version: u8,
            release: ProductReleaseId,
        },
        ForgePublish {
            schema_version: u8,
            release: ProductReleaseId,
            asset_roster_digest: ArtifactDigest,
        },
        ForgeAsset {
            schema_version: u8,
            release: ProductReleaseId,
            slot: ReleaseArtifactSlot,
            digest: ArtifactDigest,
            byte_length: u64,
        },
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
    #[serde(rename_all = "camelCase")]
    enum ObservationProvenance {
        NewlyProduced,
        AlreadyPresent,
    }

    #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    struct ObservedOperation {
        operation: ReleaseOperationId,
        evidence: ReleaseObservationEvidence,
        provenance: ObservationProvenance,
    }

    #[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    struct CompleteObservationReceipt {
        schema_version: u8,
        intent_digest: IntentDigest,
        operations: Vec<ObservedOperation>,
    }

    #[derive(Deserialize)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    struct CompleteObservationReceiptWire {
        schema_version: u8,
        intent_digest: IntentDigest,
        operations: Vec<ObservedOperation>,
    }

    struct ObservationExpectations {
        entries: BTreeMap<ReleaseArtifactSlot, (ArtifactDigest, u64)>,
        tag_annotation_digest: ArtifactDigest,
        asset_roster_digest: ArtifactDigest,
    }

    impl ObservationExpectations {
        fn from_manifest(intent: &ReleaseIntent, manifest: &ReleaseArtifactManifest) -> Result<Self, SuccessorError> {
            manifest.validate_for_intent(intent)?;
            let entries = manifest
                .entries
                .iter()
                .map(|entry| (entry.slot.clone(), (entry.digest.clone(), entry.byte_length)))
                .collect();
            let mut roster = CanonicalTranscript::intent_v1();
            for entry in &manifest.entries {
                if matches!(entry.slot, ReleaseArtifactSlot::ProductAsset { .. }) {
                    roster.push_bytes("asset", serde_json::to_vec(entry).expect("closed entry serializes"));
                }
            }
            Ok(Self {
                entries,
                tag_annotation_digest: ArtifactDigest::from_bytes(intent.source_commit.as_str()),
                asset_roster_digest: ArtifactDigest::from_bytes(roster.as_bytes()),
            })
        }
    }

    impl CompleteObservationReceipt {
        const SCHEMA_VERSION: u8 = 1;

        fn new(
            intent: &ReleaseIntent,
            expected: &ObservationExpectations,
            operations: Vec<ObservedOperation>,
        ) -> Result<Self, SuccessorError> {
            if operations
                .iter()
                .map(|entry| &entry.operation)
                .ne(intent.operations.iter().map(|operation| &operation.id))
            {
                return Err(SuccessorError::MismatchedObservationRoster);
            }
            for entry in &operations {
                validate_evidence(intent, expected, entry)?;
            }
            Ok(Self {
                schema_version: Self::SCHEMA_VERSION,
                intent_digest: intent.digest.clone(),
                operations,
            })
        }

        fn validate_for_intent(
            &self,
            intent: &ReleaseIntent,
            expected: &ObservationExpectations,
        ) -> Result<(), SuccessorError> {
            if self.schema_version != Self::SCHEMA_VERSION || self.intent_digest != intent.digest {
                return Err(SuccessorError::MismatchedObservationIntent);
            }
            Self::new(intent, expected, self.operations.clone()).map(|_| ())
        }
    }

    impl<'de> Deserialize<'de> for CompleteObservationReceipt {
        fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
        where
            D: Deserializer<'de>,
        {
            let wire = CompleteObservationReceiptWire::deserialize(deserializer)?;
            if wire.schema_version != Self::SCHEMA_VERSION {
                return Err(serde::de::Error::custom("unsupported observation receipt schema"));
            }
            Ok(Self {
                schema_version: wire.schema_version,
                intent_digest: wire.intent_digest,
                operations: wire.operations,
            })
        }
    }

    fn validate_evidence(
        intent: &ReleaseIntent,
        expected: &ObservationExpectations,
        entry: &ObservedOperation,
    ) -> Result<(), SuccessorError> {
        match (&entry.operation, &entry.evidence) {
            (
                ReleaseOperationId::RegistryArtifactPublish {
                    package,
                    version,
                    registry,
                    slot,
                },
                ReleaseObservationEvidence::RegistryArtifact {
                    schema_version: 1,
                    package: evidence_package,
                    version: evidence_version,
                    registry: evidence_registry,
                    slot: evidence_slot,
                    digest,
                    byte_length,
                },
            ) if package == evidence_package
                && version == evidence_version
                && registry == evidence_registry
                && slot == evidence_slot
                && expected.entries.get(slot) == Some(&(digest.clone(), *byte_length)) =>
            {
                Ok(())
            }
            (
                ReleaseOperationId::ProductTag { release, tag },
                ReleaseObservationEvidence::RemoteTag {
                    schema_version: 1,
                    release: evidence_release,
                    name,
                    target,
                    annotation_digest,
                },
            ) if release == evidence_release
                && tag == name
                && target == &intent.source_commit
                && annotation_digest == &expected.tag_annotation_digest =>
            {
                Ok(())
            }
            (
                ReleaseOperationId::ForgePrepare { release, .. },
                ReleaseObservationEvidence::ForgePrepare {
                    schema_version: 1,
                    release: evidence_release,
                },
            ) if release == evidence_release => Ok(()),
            (
                ReleaseOperationId::ForgePublish { release, .. },
                ReleaseObservationEvidence::ForgePublish {
                    schema_version: 1,
                    release: evidence_release,
                    asset_roster_digest,
                },
            ) if release == evidence_release && asset_roster_digest == &expected.asset_roster_digest => Ok(()),
            (
                ReleaseOperationId::ArtifactUpload { release, slot },
                ReleaseObservationEvidence::ForgeAsset {
                    schema_version: 1,
                    release: evidence_release,
                    slot: evidence_slot,
                    digest,
                    byte_length,
                },
            ) if release == evidence_release
                && slot == evidence_slot
                && expected.entries.get(slot) == Some(&(digest.clone(), *byte_length)) =>
            {
                Ok(())
            }
            _ => Err(SuccessorError::MismatchedObservationEvidence),
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
    enum SuccessorError {
        #[error("product name `{raw}` is not canonical and safe")]
        InvalidProductName { raw: String },
        #[error("coordinated release version `{version}` is not SemVer")]
        NonSemverProductVersion { version: Box<Version> },
        #[error("coordinated release has no package versions")]
        EmptyCoordinatedRoster,
                intent.product_release.clone(),
                commit(),
                intent.registry_packages.clone(),
                wrong_forge,
                intent.slots.clone()
            )
            .is_err());
        }

        #[test]
        fn manifest_metadata_and_checksum_are_bound_without_circularity() {
            let intent = intent();
            let entries = intent
                .slots
                .iter()
                .filter(|slot| {
                    matches!(
                        slot,
                        ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
                    )
                })
                .cloned()
                .map(|slot| ReleaseArtifactEntry {
                    digest: ArtifactDigest::from_bytes(slot.file_name().as_bytes()),
                    byte_length: slot.file_name().len() as u64,
                    source_commit: commit(),
                    provenance: slot.policy().clone(),
                    slot,
                })
                .collect::<Vec<_>>();
            let payloads = ValidatedPayloadEntries::new(&intent, entries).unwrap();
            let other_intent = ReleaseIntent::new(
                intent.product_release.clone(),
                CommitSha::parse(&"b".repeat(40)).unwrap(),
                intent.registry_packages.clone(),
                intent.operations.clone(),
                intent.slots.clone(),
            )
            .unwrap();
            assert!(ReleaseDistributionMetadataV1::from_payloads(&other_intent, &payloads).is_err());
            let metadata = ReleaseDistributionMetadataV1::from_payloads(&intent, &payloads).unwrap();
            let manifest = ReleaseArtifactManifest::complete(&intent, &payloads).unwrap();
            assert_eq!(manifest.entries.len(), 6);
            assert!(manifest.validate_for_intent(&intent).is_ok());
            assert_eq!(
                serde_json::from_value::<ReleaseArtifactManifest>(serde_json::to_value(&manifest).unwrap()).unwrap(),
                manifest
            );
            assert_eq!(
                serde_json::from_value::<ReleaseDistributionMetadataV1>(serde_json::to_value(&metadata).unwrap())
                    .unwrap(),
                metadata
            );
            let mut forged = manifest.clone();
            forged.entries[0].source_commit = CommitSha::parse(&"b".repeat(40)).unwrap();
            assert!(forged.validate_for_intent(&intent).is_err());
            let mut forged_metadata = manifest.clone();
            forged_metadata
                .entries
                .iter_mut()
                .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
                .unwrap()
                .byte_length += 1;
            assert!(forged_metadata.validate_for_intent(&intent).is_err());
            let mut forged_checksum = manifest.clone();
            forged_checksum
                .entries
                .iter_mut()
                .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
                .unwrap()
                .digest = ArtifactDigest::from_bytes("forged");
            assert!(forged_checksum.validate_for_intent(&intent).is_err());
            let mut metadata_wire = serde_json::to_value(metadata).unwrap();
            metadata_wire["unknown"] = serde_json::Value::Bool(true);
            assert!(serde_json::from_value::<ReleaseDistributionMetadataV1>(metadata_wire).is_err());
        }

        #[test]
        fn complete_observation_receipt_is_exact_safe_and_canonical() {
            let intent = intent();
            let payloads = ValidatedPayloadEntries::new(
                &intent,
                intent
                    .slots
                    .iter()
                    .filter(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
                    .cloned()
                    .map(|slot| ReleaseArtifactEntry {
                        digest: ArtifactDigest::from_bytes(slot.file_name()),
                        byte_length: 1,
                        source_commit: intent.source_commit.clone(),
                        provenance: slot.policy().clone(),
                        slot,
                    })
                    .collect(),
            )
            .unwrap();
            let manifest = ReleaseArtifactManifest::complete(&intent, &payloads).unwrap();
            let expected = ObservationExpectations::from_manifest(&intent, &manifest).unwrap();
            let operations = intent
                .operations
                .iter()
                .enumerate()
                .map(|(index, operation)| ObservedOperation {
                    operation: operation.id.clone(),
                    evidence: match &operation.id {
                        ReleaseOperationId::ProductTag { release, tag } => ReleaseObservationEvidence::RemoteTag {
                            schema_version: 1,
                            release: release.clone(),
                            name: tag.clone(),
                            target: intent.source_commit.clone(),
                            annotation_digest: expected.tag_annotation_digest.clone(),
                        },
                        ReleaseOperationId::ForgePrepare { release, .. } => ReleaseObservationEvidence::ForgePrepare {
                            schema_version: 1,
                            release: release.clone(),
                        },
                        ReleaseOperationId::ForgePublish { release, .. } => ReleaseObservationEvidence::ForgePublish {
                            schema_version: 1,
                            release: release.clone(),
                            asset_roster_digest: expected.asset_roster_digest.clone(),
                        },
                        ReleaseOperationId::ArtifactUpload { release, slot } => {
                            ReleaseObservationEvidence::ForgeAsset {
                                schema_version: 1,
                                release: release.clone(),
                                slot: slot.clone(),
                                digest: expected.entries[slot].0.clone(),
                                byte_length: expected.entries[slot].1,
                            }
                        }
                        ReleaseOperationId::RegistryArtifactPublish {
                            package,
                            version,
                            registry,
                            slot,
                        } => ReleaseObservationEvidence::RegistryArtifact {
                            schema_version: 1,
                            package: package.clone(),
                            version: version.clone(),
                            registry: registry.clone(),
                            slot: slot.clone(),
                            digest: ArtifactDigest::from_bytes(slot.file_name()),
                            byte_length: 1,
                        },
                    },
                    provenance: if index == 0 {
                        ObservationProvenance::NewlyProduced
                    } else {
                        ObservationProvenance::AlreadyPresent
                    },
                })
                .collect::<Vec<_>>();
            let receipt = CompleteObservationReceipt::new(&intent, &expected, operations).unwrap();
            assert!(receipt.validate_for_intent(&intent, &expected).is_ok());
            assert_eq!(
                serde_json::from_value::<CompleteObservationReceipt>(serde_json::to_value(&receipt).unwrap()).unwrap(),
                receipt
            );
            let mut unknown = serde_json::to_value(&receipt).unwrap();
            unknown["unexpected"] = serde_json::Value::Bool(true);
            assert!(serde_json::from_value::<CompleteObservationReceipt>(unknown).is_err());
            let mut missing = receipt.operations.clone();
            missing.pop();
            assert!(matches!(
                CompleteObservationReceipt::new(&intent, &expected, missing),
                Err(SuccessorError::MismatchedObservationRoster)
            ));
            let mut reordered = receipt.operations.clone();
            reordered.swap(0, 1);
            assert!(matches!(
                CompleteObservationReceipt::new(&intent, &expected, reordered),
                Err(SuccessorError::MismatchedObservationRoster)
            ));
            let mut wrong = receipt.operations.clone();
            wrong[0].evidence = ReleaseObservationEvidence::ForgePrepare {
                schema_version: 1,
                release: intent.product_release.clone(),
            };
            assert!(matches!(
                CompleteObservationReceipt::new(&intent, &expected, wrong),
                Err(SuccessorError::MismatchedObservationEvidence)
            ));
        }
    }
}

