struct ObservationFixture {
    intent: ReleaseIntent,
    manifest: ReleaseArtifactManifest,
    expected: ObservationExpectations,
    operations: Vec<ObservedOperation>,
}

impl ObservationFixture {
    fn receipt(&self) -> CompleteObservationReceipt {
        CompleteObservationReceipt::new(&self.intent, &self.expected, self.operations.clone()).unwrap()
    }

    fn operation_index(&self, predicate: impl Fn(&ReleaseOperationId) -> bool) -> usize {
        self.operations
            .iter()
            .position(|entry| predicate(&entry.operation))
            .expect("fixture contains the requested operation role")
    }

    fn assert_evidence_rejected(&self, operations: Vec<ObservedOperation>) {
        assert!(matches!(
            CompleteObservationReceipt::new(&self.intent, &self.expected, operations),
            Err(SuccessorError::MismatchedObservationEvidence)
        ));
    }
}

fn manifest_for(intent: &ReleaseIntent) -> ReleaseArtifactManifest {
    let entries = intent
        .slots
        .iter()
        .filter(|slot| {
            matches!(
                slot,
                ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
            )
        })
        .cloned()
        .map(|slot| ReleaseArtifactEntry {
            digest: ArtifactDigest::from_bytes(slot.file_name()),
            byte_length: slot.file_name().len() as u64,
            source_commit: intent.source_commit.clone(),
            provenance: slot.policy().clone(),
            slot,
        })
        .collect();
    let payloads = ValidatedPayloadEntries::new(intent, entries).unwrap();
    ReleaseArtifactManifest::complete(intent, &payloads).unwrap()
}

